    (69, 'Challenger Model', 'Consumer - Phone Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - Phone Gross adds] - [Consumer - Phone Disconnects]', NULL),
    (70, 'Challenger Model', 'Business - Phone Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - Phone Gross adds] - [Business - Phone Disconnects]', NULL),
    (71, 'Challenger Model', 'Consumer - Average Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Consumer - Phone Connections], 2)', NULL),
    (72, 'Challenger Model', 'Business - Average Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Business - Phone Connections], 2)', NULL),
    (73, 'Challenger Model', 'Consumer - Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Consumer - Phone Connections], net_adds=[Consumer - Phone Net Adds], adj=[Consumer - Phone Connections Adj])', NULL),
    (74, 'Challenger Model', 'Business - Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Business - Phone Connections], net_adds=[Business - Phone Net Adds], adj=[Business - Phone Connections Adj])', NULL),
    (75, 'Challenger Model', 'Consumer - Phone Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Consumer - Phone Disconnects], [Consumer - Average Phone Connections])', NULL),
    (76, 'Challenger Model', 'Business - Phone Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Business - Phone Disconnects], [Business - Average Phone Connections])', NULL)
  ])
),
Config AS (
  SELECT
    Config_ID,
    TRIM(LineItem) AS LineItem,
    IF((ProfitCentre IS NULL OR TRIM(ProfitCentre) = '' OR UPPER(TRIM(ProfitCentre)) IN ('ALL', 'NA')), 'ALL', TRIM(ProfitCentre)) AS ProfitCentre,
    NULLIF(TRIM(ProfitCentreHierarchyName), '') AS ProfitCentreHierarchyName,
    IF((Account IS NULL OR TRIM(Account) = '' OR UPPER(TRIM(Account)) IN ('ALL', 'NA')), 'ALL', TRIM(Account)) AS Account,
    NULLIF(TRIM(AccountHierarchy), '') AS AccountHierarchy,
    IF((ServiceType IS NULL OR TRIM(ServiceType) = '' OR UPPER(TRIM(ServiceType)) IN ('ALL', 'NA')), 'ALL', TRIM(ServiceType)) AS ServiceType,
    NULLIF(TRIM(ServiceTypeHierarchy), '') AS ServiceTypeHierarchy,
    IF((Market IS NULL OR TRIM(Market) = '' OR UPPER(TRIM(Market)) IN ('ALL', 'NA')), 'ALL', TRIM(Market)) AS Market,
    IF((Product IS NULL OR TRIM(Product) = '' OR UPPER(TRIM(Product)) IN ('ALL', 'NA')), 'ALL', TRIM(Product)) AS Product,
    NULLIF(TRIM(ProductHierarchy), '') AS ProductHierarchy,
    IF((Equipment IS NULL OR TRIM(Equipment) = '' OR UPPER(TRIM(Equipment)) IN ('ALL', 'NA')), 'ALL', TRIM(Equipment)) AS Equipment,
    NULLIF(TRIM(EquipmentHierachy), '') AS EquipmentHierachy,
    IF((DistributionChannel IS NULL OR TRIM(DistributionChannel) = '' OR UPPER(TRIM(DistributionChannel)) IN ('ALL', 'NA')), 'ALL', TRIM(DistributionChannel)) AS DistributionChannel,
    NULLIF(TRIM(DistributionChannelHierarchy), '') AS DistributionChannelHierarchy
  FROM config_csv
  WHERE (Formula IS NULL OR TRIM(Formula) = '')
),
profitcentre_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ProfitCentre) AS ProfitCentreGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ProfitCentre = H.parent
    AND H.dimension_name = 'Profit_Center'
    AND (CASE WHEN C.ProfitCentreHierarchyName IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProfitCentreHierarchyName END)
  WHERE C.ProfitCentre <> 'ALL'
),
account_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Account) AS AccountGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Account = H.parent
    AND H.dimension_name = 'Account'
    AND (CASE WHEN C.AccountHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.AccountHierarchy END)
  WHERE C.Account <> 'ALL'
),
servicetype_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ServiceType) AS ServiceTypeGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ServiceType = H.parent
    AND H.dimension_name = 'Service_Type'
    AND (CASE WHEN C.ServiceTypeHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ServiceTypeHierarchy END)
  WHERE C.ServiceType <> 'ALL'
),
market_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Market) AS MarketGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Market = H.parent
    AND H.dimension_name = 'Market'
    AND (H.is_primary = TRUE)
  WHERE C.Market <> 'ALL'
),
product_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Product) AS ProductGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Product = H.parent
    AND H.dimension_name = 'Product'
    AND (CASE WHEN C.ProductHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProductHierarchy END)
  WHERE C.Product <> 'ALL'
),
equipment_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Equipment) AS EquipmentGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Equipment = H.parent
    AND H.dimension_name = 'Equipment'
    AND (CASE WHEN C.EquipmentHierachy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.EquipmentHierachy END)
  WHERE C.Equipment <> 'ALL'
),
distributionchannel_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.DistributionChannel) AS DistributionChannelGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.DistributionChannel = H.parent
    AND H.dimension_name = 'Distribution_Channel'
    AND (CASE WHEN C.DistributionChannelHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.DistributionChannelHierarchy END)
  WHERE C.DistributionChannel <> 'ALL'
),
actuals AS (
  SELECT T.year, T.period, T.profit_center, T.Account, T.Service_Type, T.Market, T.Product, T.Equipment, T.Distribution_Channel, SUM(T.amount) AS amount
  FROM `vz-it-np-j0nv-dev-oddo-0.od_published_epm.epm_p00all_actuals_fullhist_v` T
  INNER JOIN (SELECT DISTINCT ProfitCentreGranular FROM profitcentre_mapping) F_ProfitCentre
    ON F_ProfitCentre.ProfitCentreGranular = T.profit_center
  INNER JOIN (SELECT DISTINCT AccountGranular FROM account_mapping) F_Account
    ON F_Account.AccountGranular = T.Account
  INNER JOIN (SELECT DISTINCT MarketGranular FROM market_mapping) F_Market
    ON F_Market.MarketGranular = T.Market
  INNER JOIN (SELECT DISTINCT ProductGranular FROM product_mapping) F_Product
    ON F_Product.ProductGranular = T.Product
  INNER JOIN (SELECT DISTINCT DistributionChannelGranular FROM distributionchannel_mapping) F_DistributionChannel
    ON F_DistributionChannel.DistributionChannelGranular = T.Distribution_Channel
  WHERE T.year IN (
      SELECT FORMAT_DATE('FY%y', DATE_SUB(DATE_ADD(CURRENT_DATE(), INTERVAL 0 MONTH), INTERVAL i YEAR))
      FROM UNNEST(GENERATE_ARRAY(0, 4)) AS i)
  GROUP BY T.year, T.period, T.profit_center, T.Account, T.Service_Type, T.Market, T.Product, T.Equipment, T.Distribution_Channel
),
base_values AS (
  SELECT C.LineItem, A.year AS year, A.period AS month, SUM(A.amount) AS Amount
  FROM actuals A
  INNER JOIN profitcentre_mapping M_ProfitCentre
    ON M_ProfitCentre.ProfitCentreGranular = A.profit_center
  INNER JOIN Config C
    ON C.Config_ID = M_ProfitCentre.Config_ID
  INNER JOIN account_mapping M_Account
    ON M_Account.Config_ID = C.Config_ID
    AND M_Account.AccountGranular = A.Account
  INNER JOIN market_mapping M_Market
    ON M_Market.Config_ID = C.Config_ID
    AND M_Market.MarketGranular = A.Market
  INNER JOIN product_mapping M_Product
    ON M_Product.Config_ID = C.Config_ID
    AND M_Product.ProductGranular = A.Product
  INNER JOIN distributionchannel_mapping M_DistributionChannel
    ON M_DistributionChannel.Config_ID = C.Config_ID
    AND M_DistributionChannel.DistributionChannelGranular = A.Distribution_Channel
  LEFT JOIN servicetype_mapping M_ServiceType
    ON M_ServiceType.Config_ID = C.Config_ID
    AND M_ServiceType.ServiceTypeGranular = A.Service_Type
  LEFT JOIN equipment_mapping M_Equipment
    ON M_Equipment.Config_ID = C.Config_ID
    AND M_Equipment.EquipmentGranular = A.Equipment
  WHERE
    (C.ServiceType = 'ALL' OR M_ServiceType.Config_ID IS NOT NULL)
    AND (C.Equipment = 'ALL' OR M_Equipment.Config_ID IS NOT NULL)
  GROUP BY C.LineItem, A.year, A.period
)
SELECT LineItem, year, month, Amount
FROM base_values;
